use ingetrazo_formats::sheet_pdf::{self,Draw,Page,PathOp};
fn page()->Page {Page{size_mm:[210.,297.],origin_mm:[0.,0.],draws:vec![Draw{path:vec![PathOp::Move([20.,20.]),PathOp::Line([60.,20.]),PathOp::Line([60.,45.]),PathOp::Line([20.,45.]),PathOp::Close],stroke:Some(([0.,0.,0.,1.],0.35)),fill:Some([37./255.,147./255.,93./255.,1.]),clip:None}]}}
#[test]fn invalid_export_preserves_existing_destination(){let path=std::env::temp_dir().join(format!("sheet-pdf-{}.pdf",uuid::Uuid::new_v4()));std::fs::write(&path,b"existing destination").unwrap();let mut p=page();p.draws[0].path.push(PathOp::Line([f32::NAN,0.]));assert!(sheet_pdf::save(&path,&[p]).is_err());assert_eq!(std::fs::read(&path).unwrap(),b"existing destination");std::fs::remove_file(path).unwrap();}
#[test]fn empty_atlas_or_invalid_stroke_is_refused(){assert!(sheet_pdf::encode(&[]).is_err());let mut p=page();p.draws[0].stroke.as_mut().unwrap().1=0.;assert!(sheet_pdf::encode(&[p]).is_err());}
#[test]fn valid_physical_vector_page_contains_no_image_or_process(){let bytes=sheet_pdf::encode(&[page()]).unwrap();let s=String::from_utf8_lossy(&bytes);assert!(s.starts_with("%PDF-"));assert!(s.contains("/MediaBox"));assert!(s.contains("/ExtGState"));assert!(!s.contains("/Subtype /Image"));}
